export function feedbackAnatomy(lang: Lang): Record<string, Entry> {
  const index = LANGS.indexOf(lang);
  return Object.fromEntries(Object.entries(entries).map(([key, e]) => [key, { related: e.related, sources: e.sources, ...(e.summary ? { summary: e.summary[index] } : {}), ...(e.function ? { function: e.function[index] } : {}), ...(e.location ? { location: e.location[index] } : {}) }]));
}
